// English grammar lessons, one per grammar point (P.skills): an intro, the course in parts, examples, traps, a tip.
// Shown in Cours › Grammaire. Written for Pablolinguo.
(function(){
const P = window.PACKS && window.PACKS.en; if(!P) return;
P.lessons = Object.assign(P.lessons || {}, {
"did":{"intro":"Tu racontes ton week-end à un collègue anglais, et il te pose des questions. Pour demander ou nier quelque chose au passé, l'anglais utilise un petit outil : did.","parts":[{"h":"Le principe","p":"À l'affirmative, le verbe porte lui-même le passé : I worked, I went.\n\nÀ la question et à la négation, c'est did qui porte le passé. Le verbe, lui, revient à sa forme de base, celle du dictionnaire.","rows":[["affirmation","I went to the cinema.","le verbe est au passé"],["question","Did you go to the cinema?","did + base"],["négation","I didn't go to the cinema.","didn't + base"],["réponse courte","Yes, I did. / No, I didn't.","on reprend did, sans le verbe"]]},{"h":"Un seul passé par phrase","p":"Le passé ne se marque qu'une fois. S'il est déjà dans did, il ne doit pas revenir dans le verbe.\n\nDonc pas de -ed et pas de forme irrégulière après did : Did you see? et jamais Did you saw?"},{"h":"Les questions avec un mot interrogatif","p":"Avec where, what, when ou why, l'ordre reste le même : mot interrogatif, puis did, puis le sujet, puis la base.\n\nWhere did you go? What did she say? Why didn't they come?","rows":[["Where did you go?","Où es-tu allé ?",""],["What did he buy?","Qu'est-ce qu'il a acheté ?",""],["Why didn't you call?","Pourquoi tu n'as pas appelé ?","didn't dans une question"]]},{"h":"Attention au verbe be","p":"Le verbe be ne prend pas did. Au passé, il a ses propres formes : was et were.\n\nOn dit Were you tired? et I wasn't there, pas Did you be tired?"}],"ex":[["Did you sleep well?","Tu as bien dormi ?",""],["I didn't know that.","Je ne savais pas ça.","know, pas knew, après didn't"],["Did she call you back?","Elle t'a rappelé ?",""],["We didn't have time to eat.","On n'a pas eu le temps de manger.","have, pas had"],["What did you do last night?","Qu'est-ce que tu as fait hier soir ?","le premier do est la base"],["They didn't come to the party.","Ils ne sont pas venus à la fête.",""],["Did it rain in Lyon yesterday?","Il a plu à Lyon hier ?",""],["Why didn't you tell me?","Pourquoi tu ne me l'as pas dit ?",""]],"traps":[["Did you went to the gym?","Did you go to the gym?","Did porte déjà le passé : le verbe reste à la base."],["I didn't saw him.","I didn't see him.","Après didn't, jamais de forme irrégulière."],["Did you was at home?","Were you at home?","Avec be, on n'utilise pas did : was ou were suffit."]],"tip":"Le passé ne se dit qu'une fois : s'il est dans did, le verbe reste nu."},
"does":{"intro":"Tu présentes ta sœur ou ton coloc à quelqu'un : ce qu'il aime, ce qu'il ne mange pas. Au présent, avec he, she ou it, l'anglais ajoute un -s, mais jamais à deux endroits.","parts":[{"h":"Le -s de la troisième personne","p":"Au présent simple, le verbe prend un -s avec he, she, it, et avec un nom au singulier (my brother, Paul, the shop).\n\nAvec I, you, we et they, il ne bouge pas : I work, she works.","rows":[["I / you / we / they","They live in Lille.","pas de -s"],["he / she / it","She lives in Lille.","-s"],["verbe en -o, -sh, -ch, -ss, -x","He goes, she watches","on ajoute -es"],["consonne + y","It carries, she studies","y devient ies"],["have","He has a car.","forme spéciale"]]},{"h":"Question et négation : does prend le -s","p":"Pour poser une question ou dire non, on ajoute does ou doesn't. Le -s passe alors dans does, et le verbe redevient nu.\n\nShe works, mais Does she work? et She doesn't work.","rows":[["affirmation","He plays tennis.","le -s est sur le verbe"],["question","Does he play tennis?","le -s est dans does"],["négation","He doesn't play tennis.","le -s est dans doesn't"],["réponse courte","Yes, he does. / No, he doesn't.",""]]},{"h":"Jamais les deux","p":"Le -s ne s'écrit qu'une fois par phrase. Soit sur le verbe, soit sur does.\n\nSi tu écris does, vérifie que le verbe juste après n'a pas de -s."}],"ex":[["My brother doesn't eat meat.","Mon frère ne mange pas de viande.",""],["Does she work on Saturdays?","Est-ce qu'elle travaille le samedi ?",""],["He takes the bus every morning.","Il prend le bus tous les matins.","le -s est sur takes"],["It doesn't matter.","Ça n'a pas d'importance.",""],["Where does your sister live?","Où habite ta sœur ?",""],["Paul watches a lot of series.","Paul regarde beaucoup de séries.","watch devient watches"],["Does the shop open on Sundays?","Le magasin ouvre le dimanche ?",""],["She has two cats.","Elle a deux chats.","has, pas haves"]],"traps":[["She doesn't works here.","She doesn't work here.","Le -s est déjà dans doesn't."],["Does he likes pizza?","Does he like pizza?","Après does, le verbe reste nu."],["My mother work in a bank.","My mother works in a bank.","Avec un nom au singulier, il faut le -s."]],"tip":"Un seul -s par phrase : sur le verbe ou sur does, jamais sur les deux."},
"questions":{"intro":"À l'office de tourisme, au restaurant, à un nouveau collègue : tu poses des questions toute la journée. En anglais, leur ordre suit une formule fixe, qu'on peut retenir avec le mot QUASI.","parts":[{"h":"La formule QUASI","p":"QUASI : Question (le mot interrogatif), Auxiliaire, Sujet, Infinitif (le verbe à sa base).\n\nLe mot interrogatif vient en premier, puis l'auxiliaire (do, does, did, can, will…), puis le sujet, puis le verbe.","rows":[["Where + do + you + live","Where do you live?","présent"],["What + does + she + want","What does she want?","présent, he / she / it"],["Why + did + he + leave","Why did he leave?","passé"],["How + can + I + help","How can I help?","avec un modal"]]},{"h":"Sans mot interrogatif","p":"Pour une question fermée (réponse oui ou non), on commence directement par l'auxiliaire.\n\nDo you like jazz? Can you swim? Did they win?"},{"h":"Avec be, pas de do","p":"Le verbe be est son propre auxiliaire. Il passe simplement devant le sujet.\n\nIt is big devient Is it big? He is at home devient Where is he?","rows":[["It is big.","Is it big?","be passe devant"],["They are late.","Why are they late?",""],["She was there.","Was she there?","aussi au passé"]]},{"h":"Le piège du français","p":"En français, on peut garder l'ordre normal et monter la voix : Tu habites où ? En anglais, ça ne marche pas à l'écrit.\n\nEt « est-ce que » ne se traduit pas mot à mot : c'est l'auxiliaire qui joue ce rôle."}],"ex":[["Where do you live?","Où est-ce que tu habites ?",""],["Is your flat big?","Ton appartement est grand ?","be, donc pas de do"],["Why did he leave early?","Pourquoi il est parti tôt ?",""],["Where does it hurt?","Où est-ce que tu as mal ?","mot à mot : où est-ce que ça fait mal"],["What time does the train leave?","Le train part à quelle heure ?",""],["Can you help me?","Tu peux m'aider ?",""],["Where are my keys?","Où sont mes clés ?",""],["How long did you stay in Spain?","Tu es resté combien de temps en Espagne ?",""]],"traps":[["Where you live?","Where do you live?","Il manque l'auxiliaire do entre le mot interrogatif et le sujet."],["Do you are tired?","Are you tired?","Avec be, on n'ajoute pas do."],["Why he left early?","Why did he leave early?","Au passé, il faut did, et le verbe revient à la base."]],"tip":"Pense QUASI : mot interrogatif, auxiliaire, sujet, verbe, et be passe devant tout seul."},
"bedo":{"intro":"Il fait chaud, tu as faim, tu as 30 ans : en français, on dit ça avec faire ou avoir. En anglais, on utilise presque toujours be.","parts":[{"h":"Une seule formule : be + adjectif","p":"Pour la météo, les sensations et l'âge, l'anglais dit ce que tu es, pas ce que tu as.\n\nOn conjugue be (am, is, are) et on ajoute un adjectif.","rows":[["Il fait froid.","It's cold.","météo : it + be"],["Il fait beau.","It's sunny. / It's nice.",""],["J'ai faim.","I'm hungry.","sensation : je suis affamé"],["J'ai soif.","I'm thirsty.",""],["J'ai froid.","I'm cold.","c'est toi qui as froid"],["J'ai 30 ans.","I'm 30.","âge : je suis 30"]]},{"h":"Pour la météo, le sujet est it","p":"En français, on dit « il fait ». En anglais, le sujet est it, et le verbe est be : it's hot, it's windy, it's raining.\n\nAu futur, c'est la même idée avec will : it will be sunny."},{"h":"L'âge","p":"Pour l'âge, on dit juste le nombre après be : she's 25. On peut ajouter years old, mais jamais years seul.\n\nPour demander : How old are you? Mot à mot : tu es vieux comment ?"},{"h":"Les autres sensations","p":"Même logique pour avoir chaud (be hot), avoir peur (be scared), avoir raison (be right), avoir tort (be wrong).\n\nQuand le français dit « avoir » avec une sensation, pense d'abord à be."}],"ex":[["It's cold today.","Il fait froid aujourd'hui.",""],["I'm thirsty, can I have some water?","J'ai soif, je peux avoir de l'eau ?",""],["My sister is 25.","Ma sœur a 25 ans.",""],["It will be sunny tomorrow.","Il fera beau demain.",""],["Are you hungry?","Tu as faim ?",""],["You're right, it's too late.","Tu as raison, c'est trop tard.","avoir raison = be right"],["How old is your son?","Quel âge a ton fils ?",""],["I'm hot, can you open the window?","J'ai chaud, tu peux ouvrir la fenêtre ?",""]],"traps":[["I have hungry.","I'm hungry.","La faim se dit avec be, pas avec have."],["I have 30 years.","I'm 30.","L'âge se dit avec be, sans have."],["It makes cold.","It's cold.","La météo se dit avec be, pas avec make."]],"tip":"Faim, soif, froid, âge : en anglais, tu ne les as pas, tu les es."},
"simplecont":{"intro":"Tu prends le bus tous les jours, mais aujourd'hui tu marches. Le français dit les deux avec le même présent. L'anglais, lui, a deux présents différents.","parts":[{"h":"Le présent simple : ce qui se répète","p":"On l'utilise pour les habitudes et les vérités générales : ce que tu fais d'habitude, souvent, jamais.\n\nI work in Paris. She never drinks coffee. Water boils at 100 degrees."},{"h":"Le présent continu : ce qui se passe maintenant","p":"On l'utilise pour une action en cours, ou une situation temporaire.\n\nIl se forme avec be (am, is, are) et le verbe en -ing : I'm working, she's sleeping.","rows":[["I","I'm walking.","am"],["he / she / it","She's walking.","is"],["you / we / they","They're walking.","are"],["négation","I'm not walking.",""],["question","Are you walking?",""]]},{"h":"Les mots qui aident","p":"Certains mots annoncent souvent l'un ou l'autre. Ce n'est pas une règle absolue, mais c'est un bon indice.","rows":[["usually, always, never, every day","I usually take the bus.","présent simple"],["now, right now, at the moment, today","Today I'm walking.","présent continu"],["this week, these days","I'm working from home this week.","temporaire, donc continu"]]},{"h":"Les verbes d'état","p":"Certains verbes décrivent un état, pas une action : know, like, want, need, understand. Ils restent au présent simple, même maintenant.\n\nOn dit I know, et pas I'm knowing."}],"ex":[["I usually take the bus, but today I'm walking.","D'habitude je prends le bus, mais aujourd'hui je marche.",""],["What are you doing right now?","Qu'est-ce que tu fais en ce moment ?",""],["She never drinks coffee.","Elle ne boit jamais de café.",""],["It's raining, take an umbrella.","Il pleut, prends un parapluie.","en cours"],["My parents live in Nantes.","Mes parents habitent à Nantes.","situation stable"],["I'm staying with a friend this week.","Je loge chez un ami cette semaine.","temporaire"],["Do you understand?","Tu comprends ?","verbe d'état"],["He plays football every Sunday.","Il joue au foot tous les dimanches.",""]],"traps":[["I'm usually taking the bus.","I usually take the bus.","Une habitude se dit au présent simple."],["Look, it rains!","Look, it's raining!","Une action en cours se dit avec be + -ing."],["I'm knowing the answer.","I know the answer.","Know est un verbe d'état : pas de -ing."]],"tip":"D'habitude, présent simple ; en ce moment, be + -ing."},
"particles":{"intro":"Mettre ta veste, descendre du bus, ne plus avoir de lait : en anglais, beaucoup de ces gestes du quotidien se disent avec un verbe suivi d'un petit mot.","parts":[{"h":"Un petit mot qui change tout","p":"Un phrasal verb, c'est un verbe suivi d'une particule (on, off, up, out…). Ensemble, ils forment un sens nouveau.\n\nPut veut dire poser, mais put on veut dire mettre un vêtement. Si tu enlèves on, la phrase ne veut plus rien dire.","rows":[["put on","Put your jacket on.","mettre un vêtement"],["take off","Take your shoes off.","enlever"],["try on","Try this jacket on.","essayer un vêtement"],["get on / get off","Get off the bus here.","monter / descendre d'un transport"],["run out of","We've run out of milk.","ne plus avoir de"],["turn on / turn off","Turn off the light.","allumer / éteindre"]]},{"h":"Où placer le complément","p":"Avec beaucoup de ces verbes, le complément peut aller avant ou après la particule : put on your jacket ou put your jacket on.\n\nMais avec un pronom (it, them), il va toujours au milieu : put it on, jamais put on it."},{"h":"Ne pas ajouter de mot en trop","p":"Le français pousse à ajouter « de » : descendre du bus. Mais get off suffit : get off the bus, sans of.\n\nÀ l'inverse, run out a besoin de of devant ce qui manque : run out of milk. Chaque phrasal verb a sa forme exacte, à apprendre en bloc."}],"ex":[["Put your jacket on, it's cold.","Mets ta veste, il fait froid.",""],["We've run out of milk.","On n'a plus de lait.",""],["Get off the bus at the next stop.","Descends du bus au prochain arrêt.","pas de of"],["Can I try these shoes on?","Je peux essayer ces chaussures ?",""],["Turn the TV off, please.","Éteins la télé, s'il te plaît.",""],["Take your coat off and sit down.","Enlève ton manteau et assieds-toi.",""],["The car ran out of petrol.","La voiture est tombée en panne d'essence.",""],["I like this shirt. Can I try it on?","J'aime cette chemise. Je peux l'essayer ?","it au milieu"]],"traps":[["Get off of the bus.","Get off the bus.","Get off se suffit : pas de of après."],["We've run out milk.","We've run out of milk.","Run out demande of devant ce qui manque."],["Put on it.","Put it on.","Un pronom se place entre le verbe et la particule."]],"tip":"Un phrasal verb s'apprend en bloc, avec son petit mot exact, ni plus ni moins."},
"unless":{"intro":"Tu viendras, sauf s'il pleut. Pour poser une condition négative, l'anglais a un mot très pratique : unless.","parts":[{"h":"Unless = si… ne… pas","p":"Unless veut dire « sauf si » ou « à moins que ». Il contient déjà la négation.\n\nI'll come unless it rains veut dire la même chose que I'll come if it doesn't rain.","rows":[["if… not","I'll come if it doesn't rain.","deux mots, une négation"],["unless","I'll come unless it rains.","la négation est dans unless"]]},{"h":"Le présent après unless","p":"Comme après if, on met le présent après unless, même si on parle du futur.\n\nLe will va dans l'autre partie de la phrase : We'll go climbing unless you're tired. Jamais unless you will be tired."},{"h":"Ne pas confondre avec at least","p":"Les deux se ressemblent un peu à l'oreille, mais n'ont rien à voir. At least veut dire « au moins » et parle d'une quantité ou d'un minimum.\n\nThere were at least twenty people : il y avait au moins vingt personnes.","rows":[["unless","Don't call unless it's urgent.","sauf si"],["at least","Call at least once a week.","au moins"]]}],"ex":[["I'll come unless it rains.","Je viendrai, sauf s'il pleut.",""],["We'll go climbing unless you're tired.","On ira grimper, à moins que tu sois fatigué.",""],["Don't leave unless it's urgent.","Ne pars pas, à moins que ce soit urgent.",""],["There were at least twenty people.","Il y avait au moins vingt personnes.","quantité"],["You won't pass unless you work harder.","Tu ne réussiras pas, sauf si tu travailles plus.",""],["I don't drink coffee unless I'm really tired.","Je ne bois pas de café, sauf si je suis vraiment fatigué.",""],["It takes at least an hour by car.","Il faut au moins une heure en voiture.",""]],"traps":[["I'll come unless it will rain.","I'll come unless it rains.","Après unless, on met le présent, pas will."],["I'll come unless it doesn't rain.","I'll come unless it rains.","Unless contient déjà la négation : on n'en ajoute pas."],["There were unless twenty people.","There were at least twenty people.","Pour une quantité minimum, c'est at least."]],"tip":"Unless, c'est if not en un seul mot, toujours suivi du présent."},
"although":{"intro":"Il est tard, mais tu travailles encore ; tu iras courir, même s'il pleut. Pour nuancer, l'anglais a des mots qu'on confond facilement : although, even if, still et always.","parts":[{"h":"Although : bien que, c'est vrai","p":"Although présente un fait réel, qui pourrait empêcher la suite, mais ne l'empêche pas.\n\nAlthough it's late, I'm working : il est vraiment tard. Après although, le verbe est à l'indicatif, comme une phrase normale."},{"h":"Even if : même si, on imagine","p":"Even if parle d'une situation possible, pas encore réelle. On ne sait pas s'il va pleuvoir.\n\nEven if it rains tomorrow, we'll go. Comme après if, on met le présent pour parler du futur.","rows":[["although","Although it's raining, we're going out.","il pleut vraiment"],["even if","Even if it rains, we'll go out.","il pleuvra peut-être"],["even though","Even though it's raining, we're going out.","comme although, plus fort"]]},{"h":"Still ou always ?","p":"Le français « toujours » a deux sens, et l'anglais a deux mots.\n\nStill, c'est toujours au sens d'encore : la situation continue. Always, c'est toujours au sens de tout le temps, à chaque fois.","rows":[["still","I still have a headache.","j'ai encore mal"],["always","I always have a headache on Mondays.","chaque lundi"]]}],"ex":[["Although it's late, I'm still working.","Bien qu'il soit tard, je travaille encore.",""],["I still have a headache.","J'ai toujours mal à la tête.","encore"],["Even if it rains tomorrow, we'll go.","Même s'il pleut demain, on ira.",""],["She always forgets her keys.","Elle oublie toujours ses clés.","à chaque fois"],["Although he's rich, he lives simply.","Bien qu'il soit riche, il vit simplement.",""],["Are you still living in Bordeaux?","Tu habites toujours à Bordeaux ?","encore"],["I'll finish it, even if it takes all night.","Je le finirai, même si ça prend toute la nuit.",""]],"traps":[["I always have a headache since this morning.","I still have a headache.","Pour dire que ça continue, c'est still."],["Even if it's late, I'm working.","Although it's late, I'm working.","Il est vraiment tard : c'est un fait, donc although."],["Even if it will rain, we'll go.","Even if it rains, we'll go.","Après even if, on met le présent pour le futur."]],"tip":"Although pour le réel, even if pour l'imaginé, still pour ce qui dure encore."},
"future":{"intro":"Ce week-end, tu vois tes parents ; tu penses qu'il va pleuvoir. En anglais, le futur ne se dit pas toujours avec will : tout dépend de ce qui est déjà prévu.","parts":[{"h":"Ce qui est déjà décidé","p":"Pour un projet que tu as déjà en tête, on utilise be going to + base : I'm going to see my parents.\n\nSi c'est vraiment organisé (une heure, un rendez-vous, des billets), on dit aussi le présent continu : I'm seeing them on Friday."},{"h":"Ce qu'on prédit ou décide sur le moment","p":"Will sert à prédire, surtout avec I think, I'm sure, probably. Il sert aussi à décider à l'instant même, sans plan avant.\n\nI think it will rain. Le téléphone sonne : I'll get it, je décroche.","rows":[["plan décidé","I'm going to buy a bike.","be going to"],["rendez-vous fixé","I'm seeing the dentist on Monday.","présent continu"],["prédiction","I think it will rain.","will"],["décision immédiate","I'll call you back.","will"],["promesse, offre","I'll help you.","will"]]},{"h":"Demander les projets de quelqu'un","p":"Pour savoir ce que quelqu'un a prévu, on utilise le présent continu : What are you doing tonight?\n\nWhat will you do tonight? existe, mais sonne moins naturel pour des projets."}],"ex":[["This weekend, I'm going to see my parents.","Ce week-end, je vais voir mes parents.","plan"],["I think it will rain.","Je pense qu'il pleuvra.","après I think"],["What are you doing tonight?","Qu'est-ce que tu fais ce soir ?",""],["I'm seeing them on Friday.","Je les vois vendredi.","rendez-vous fixé"],["It's heavy, I'll carry it for you.","C'est lourd, je vais te le porter.","décision sur le moment"],["She's going to start a new job.","Elle va commencer un nouveau travail.",""],["We're flying to Rome next week.","On prend l'avion pour Rome la semaine prochaine.",""],["Don't worry, you'll be fine.","Ne t'inquiète pas, ça ira.","prédiction"]],"traps":[["I think it rains tomorrow.","I think it will rain tomorrow.","Une prédiction ne se dit pas au présent simple : après I think, c'est will."],["What do you do tonight?","What are you doing tonight?","Pour des projets, on utilise le présent continu."],["I go to see my parents this weekend.","I'm going to see my parents this weekend.","Le présent simple ne dit pas un projet."]],"tip":"Déjà prévu : going to ou -ing ; décidé ou prédit maintenant : will."},
"presperf":{"intro":"Tu es déjà allé au Canada ? Tu as fini ? Pour parler d'une expérience ou d'une action sans dire quand, l'anglais utilise le present perfect.","parts":[{"h":"La forme","p":"Have (ou has avec he, she, it) + participe passé. Le participe passé, c'est la forme en -ed, ou la troisième colonne pour les verbes irréguliers.","rows":[["I / you / we / they","I've finished.","have"],["he / she / it","She's finished.","has"],["négation","I haven't finished.",""],["question","Have you finished?",""],["irrégulier","I've seen, I've eaten, I've been","3e colonne"]]},{"h":"Quand l'utiliser","p":"Pour une expérience de vie, souvent avec ever (déjà) et never (jamais) : I've never been to Canada.\n\nPour une action sans moment précis, souvent avec already (déjà) et yet (encore, dans les questions et négations) : I haven't finished yet."},{"h":"Si tu dis quand, c'est le past simple","p":"Dès que tu donnes un moment terminé (yesterday, last week, in 2020), tu passes au past simple.\n\nLe français dit « je suis allé » dans les deux cas. L'anglais, lui, regarde si le moment est précisé.","rows":[["sans moment","I've been to Rome.","present perfect"],["avec moment","I went to Rome in 2020.","past simple"],["sans moment","Have you seen this film?",""],["avec moment","Did you see it last night?",""]]},{"h":"Been ou gone ?","p":"Pour un voyage, on dit been to : I've been to Canada, j'y suis allé et revenu. He's gone to Canada veut dire qu'il y est encore."}],"ex":[["I've never been to Canada.","Je ne suis jamais allé au Canada.",""],["Have you ever eaten sushi?","Tu as déjà mangé des sushis ?",""],["I haven't finished yet.","Je n'ai pas encore fini.","yet en fin de phrase"],["She's already left.","Elle est déjà partie.",""],["I saw him yesterday.","Je l'ai vu hier.","moment précis, donc past simple"],["Have you seen my phone?","Tu as vu mon téléphone ?",""],["We've lost the keys.","On a perdu les clés.",""]],"traps":[["I've seen him yesterday.","I saw him yesterday.","Avec un moment précis, c'est le past simple."],["I never went to Canada.","I've never been to Canada.","Une expérience de vie se dit au present perfect."],["I haven't finished already.","I haven't finished yet.","Dans une négation, « pas encore » se dit not… yet, pas already."]],"tip":"Pas de date, present perfect ; une date, past simple."},
"havebeen":{"intro":"Tu apprends l'anglais depuis deux mois, il pleut depuis ce matin. Pour une action qui a commencé et qui continue, l'anglais n'utilise pas le présent comme le français.","parts":[{"h":"Have been + -ing : depuis, et ça continue","p":"Le français dit « j'apprends depuis ». L'anglais dit littéralement « j'ai été en train d'apprendre » : I've been learning.\n\nForme : have ou has + been + verbe en -ing.","rows":[["I / you / we / they","I've been waiting.","have been"],["he / she / it","It's been raining.","has been, contracté en 's"],["question","How long have you been working here?","depuis combien de temps"],["négation","I haven't been sleeping well.",""]]},{"h":"For ou since ?","p":"For se met devant une durée : for two months, for an hour.\n\nSince se met devant un point de départ : since this morning, since 2019, since Monday.","rows":[["for + durée","for three years","depuis trois ans"],["since + point de départ","since January","depuis janvier"]]},{"h":"Has been + participe passé : le passif","p":"Attention, been peut aussi servir au passif. Has been + participe passé veut dire « a été fait » : The meeting has been cancelled.\n\nPour les distinguer, regarde le verbe après been : -ing, c'est une action qui dure ; participe passé, c'est quelque chose qu'on a fait au sujet."}],"ex":[["I've been learning English for two months.","J'apprends l'anglais depuis deux mois.","durée"],["It's been raining since this morning.","Il pleut depuis ce matin.","point de départ"],["The meeting has been cancelled.","La réunion a été annulée.","passif"],["How long have you been waiting?","Tu attends depuis combien de temps ?",""],["She's been working here since 2019.","Elle travaille ici depuis 2019.",""],["I've been climbing for three years.","Je grimpe depuis trois ans.",""],["My car has been repaired.","Ma voiture a été réparée.","passif"]],"traps":[["I learn English since two months.","I've been learning English for two months.","Avec depuis, l'anglais n'utilise pas le présent, et une durée prend for."],["It's been raining for this morning.","It's been raining since this morning.","Un point de départ demande since."],["The meeting has been cancelling.","The meeting has been cancelled.","Au passif, on met le participe passé, pas -ing."]],"tip":"Depuis et ça dure : have been + -ing, avec for pour une durée et since pour un départ."},
"ingto":{"intro":"Tu as arrêté de fumer, tu as besoin de dormir, tu as hâte de voir un ami. Quand deux verbes se suivent, le second prend soit -ing, soit to : c'est le premier qui décide.","parts":[{"h":"Les verbes suivis de -ing","p":"Après certains verbes, le second verbe prend -ing. Ce sont souvent des verbes qui parlent d'une activité qu'on fait ou qu'on arrête.","rows":[["stop","I stopped smoking.","arrêter de"],["enjoy","I enjoy cooking.","aimer faire"],["finish","Have you finished eating?","finir de"],["avoid","Avoid driving at night.","éviter de"],["look forward to","I'm looking forward to seeing you.","avoir hâte de"]]},{"h":"Les verbes suivis de to","p":"Après d'autres verbes, on met to + base. Ce sont souvent des verbes tournés vers l'avenir : vouloir, décider, espérer.","rows":[["want","I want to go home.","vouloir"],["need","I need to sleep.","avoir besoin de"],["decide","She decided to stay.","décider de"],["learn","I'm learning to swim.","apprendre à"],["hope","We hope to see you soon.","espérer"]]},{"h":"Le piège de look forward to","p":"Dans look forward to, to n'annonce pas un verbe à la base. C'est une préposition, comme « à » dans « penser à ».\n\nDonc on dit looking forward to seeing you, avec -ing après to."}],"ex":[["I stopped smoking last year.","J'ai arrêté de fumer l'an dernier.",""],["I need to sleep.","J'ai besoin de dormir.",""],["I'm looking forward to seeing you.","J'ai hâte de te voir.","to + -ing"],["I decided to learn to climb.","J'ai décidé d'apprendre à grimper.","deux fois to"],["Do you enjoy working from home?","Tu aimes travailler de chez toi ?",""],["She wants to move to Spain.","Elle veut déménager en Espagne.",""],["Try to avoid eating late.","Essaie d'éviter de manger tard.",""],["Have you finished reading the book?","Tu as fini de lire le livre ?",""]],"traps":[["I stopped to smoke.","I stopped smoking.","Stop to smoke veut dire s'arrêter pour fumer, pas arrêter de fumer."],["I'm looking forward to see you.","I'm looking forward to seeing you.","Dans look forward to, to est suivi de -ing."],["I need sleeping.","I need to sleep.","Need est suivi de to + base."]],"tip":"Arrêter, finir, aimer, éviter : -ing ; vouloir, décider, espérer : to."},
"makedo":{"intro":"Faire un gâteau, faire la vaisselle, faire une erreur : en français, tout se fait avec faire. L'anglais partage ce travail entre make et do.","parts":[{"h":"Make : on crée quelque chose","p":"Make sert quand on fabrique, crée ou produit quelque chose qui n'existait pas avant.\n\nOn l'utilise aussi dans des expressions fixes, comme a mistake ou a decision.","rows":[["make a cake","faire un gâteau","on fabrique"],["make dinner","faire à dîner",""],["make a mistake","faire une erreur","expression fixe"],["make a decision","prendre une décision",""],["make noise","faire du bruit",""]]},{"h":"Do : on fait une tâche","p":"Do sert pour une tâche, un travail ou une activité. On ne crée rien de nouveau, on accomplit quelque chose.","rows":[["do the dishes","faire la vaisselle","tâche"],["do homework","faire ses devoirs",""],["do sport","faire du sport","activité"],["do the shopping","faire les courses",""],["do your best","faire de ton mieux",""]]},{"h":"Quand tu hésites","p":"Demande-toi : est-ce qu'à la fin il y a un objet nouveau ? Si oui, make. Sinon, do.\n\nPour les expressions fixes (mistake, decision, friends, money), le mieux est de les apprendre telles quelles."}],"ex":[["I made a mistake.","J'ai fait une erreur.",""],["Did you do the dishes?","Tu as fait la vaisselle ?",""],["I'm making a cake.","Je fais un gâteau.",""],["She does yoga every morning.","Elle fait du yoga tous les matins.",""],["Can you make some coffee?","Tu peux faire du café ?",""],["I have to do my homework.","Je dois faire mes devoirs.",""],["We need to make a decision.","On doit prendre une décision.",""],["Don't make so much noise.","Ne fais pas autant de bruit.",""]],"traps":[["I did a mistake.","I made a mistake.","Mistake va toujours avec make."],["I make my homework.","I do my homework.","Les devoirs sont une tâche : do."],["Can you do a cake?","Can you make a cake?","Un gâteau, on le fabrique : make."]],"tip":"Make fabrique, do accomplit."},
"shall":{"intro":"On mange au resto ce soir ? Je t'aide ? Pour proposer quelque chose, poliment et simplement, l'anglais a une petite formule : Shall we… ? ou Shall I… ?","parts":[{"h":"Shall we… ? : on fait… ?","p":"Shall we propose de faire quelque chose ensemble. C'est l'équivalent de « on fait… ? » ou « et si on… ? ».\n\nLe verbe reste à la base, sans to : Shall we go?"},{"h":"Shall I… ? : je fais… ?","p":"Shall I propose de faire quelque chose pour l'autre. C'est l'équivalent de « je fais… ? » ou « tu veux que je… ? ».\n\nShall I open the window? : j'ouvre la fenêtre ?","rows":[["Shall we + base","Shall we start?","on commence ?"],["Shall I + base","Shall I help you?","je t'aide ?"],["mot interrogatif + shall","What shall we do?","qu'est-ce qu'on fait ?"],["Where shall we… ?","Where shall we meet?","on se retrouve où ?"]]},{"h":"Répondre","p":"Pour accepter : Yes, let's! ou Good idea! Pour Shall I : Yes, please! ou No, thanks, I'm fine.\n\nShall ne s'utilise presque plus qu'avec I et we, dans ces propositions. C'est surtout de l'anglais britannique, mais il est compris partout."}],"ex":[["Shall we eat out tonight?","On mange au restaurant ce soir ?",""],["Shall I help you?","Je t'aide ?",""],["Shall we go?","On y va ?",""],["What shall we do this weekend?","Qu'est-ce qu'on fait ce week-end ?",""],["Shall I close the door?","Je ferme la porte ?",""],["Where shall we meet?","On se retrouve où ?",""],["Shall we take a taxi?","On prend un taxi ?",""]],"traps":[["Shall we to go?","Shall we go?","Après shall, le verbe est à la base, sans to."],["We shall go?","Shall we go?","Dans une question, shall passe devant le sujet."],["Shall we going?","Shall we go?","Pas de -ing après shall."]],"tip":"Shall we pour « on fait ? », Shall I pour « je fais ? », et le verbe reste nu."},
"while":{"intro":"Tu cuisinais quand le téléphone a sonné. Pour raconter une histoire, l'anglais distingue l'action de fond, qui dure, et l'action courte, qui la coupe.","parts":[{"h":"Le past continuous : l'action de fond","p":"Il décrit une action qui était en cours à un moment du passé. C'est souvent l'équivalent de l'imparfait : je cuisinais, il pleuvait.\n\nForme : was ou were + verbe en -ing.","rows":[["I / he / she / it","I was cooking.","was"],["you / we / they","They were sleeping.","were"],["négation","She wasn't listening.",""],["question","What were you doing?",""]]},{"h":"L'action courte : past simple","p":"L'événement qui arrive au milieu, d'un coup, se met au past simple : the phone rang, I went out.\n\nWhile introduit en général l'action longue, when l'action courte. Mais on peut aussi dire It was raining when I went out."},{"h":"Les deux ensemble","p":"La phrase type mélange les deux temps : une action longue, coupée par une action courte.","rows":[["While I was cooking, the phone rang.","Pendant que je cuisinais, le téléphone a sonné.",""],["It was raining when I went out.","Il pleuvait quand je suis sorti.",""],["I was sleeping when you called.","Je dormais quand tu as appelé.",""]]},{"h":"Un moment précis","p":"On utilise aussi le past continuous pour dire ce qu'on faisait à une heure précise : What were you doing at 8 pm yesterday?"}],"ex":[["While I was cooking, the phone rang.","Pendant que je cuisinais, le téléphone a sonné.",""],["It was raining when I went out.","Il pleuvait quand je suis sorti.",""],["What were you doing yesterday at 8 pm?","Qu'est-ce que tu faisais hier à 20 h ?",""],["I was watching TV when the power went off.","Je regardais la télé quand le courant a coupé.",""],["She wasn't listening, so she didn't hear.","Elle n'écoutait pas, alors elle n'a pas entendu.",""],["We met while we were working in London.","On s'est rencontrés pendant qu'on travaillait à Londres.",""],["Were you sleeping when I called?","Tu dormais quand j'ai appelé ?",""]],"traps":[["While I cooked, the phone was ringing.","While I was cooking, the phone rang.","L'action longue prend -ing, l'action courte est au past simple."],["I were sleeping when you called.","I was sleeping when you called.","Avec I, he, she, it, c'est was ; were va avec you, we, they."],["What you were doing at 8 pm?","What were you doing at 8 pm?","Dans une question, were passe devant le sujet."]],"tip":"Le décor en was + -ing, l'événement qui le coupe au past simple."},
"passive":{"intro":"Le pont a été construit en 1900, ton vélo a été volé, le rapport sera envoyé demain. Quand ce qui compte, c'est ce qui arrive et pas qui le fait, on utilise le passif.","parts":[{"h":"La formule","p":"Le passif, c'est be au bon temps, suivi du participe passé du verbe. Le participe ne change jamais : c'est be qui porte le temps.\n\nThe bridge was built : was dit le passé, built dit l'action.","rows":[["présent","English is spoken here.","is + pp"],["passé","The bridge was built in 1900.","was / were + pp"],["present perfect","My bike has been stolen.","has / have been + pp"],["futur","The report will be sent tomorrow.","will be + pp"],["en cours","The road is being repaired.","is being + pp"],["avec un modal","It can be done.","modal + be + pp"]]},{"h":"Quand l'utiliser","p":"On l'utilise quand l'auteur de l'action est inconnu, évident ou sans intérêt. On ne sait pas qui a volé le vélo, et ça n'a pas d'importance.\n\nSi on veut nommer l'auteur, on ajoute by : The book was written by a nurse."},{"h":"Le passif et le « on » français","p":"Le français dit souvent « on » là où l'anglais met un passif. On m'a volé mon vélo : My bike has been stolen.\n\nOn m'a dit que… : I was told that… Ce passif avec une personne comme sujet est très courant en anglais."}],"ex":[["The bridge was built in 1900.","Le pont a été construit en 1900.",""],["My bike has been stolen.","On m'a volé mon vélo.","auteur inconnu"],["The report will be sent tomorrow.","Le rapport sera envoyé demain.",""],["I was told the shop was closed.","On m'a dit que le magasin était fermé.",""],["Breakfast is served from 7 to 10.","Le petit-déjeuner est servi de 7 h à 10 h.",""],["The flight has been delayed.","Le vol a été retardé.",""],["This photo was taken by my grandfather.","Cette photo a été prise par mon grand-père.","auteur avec by"],["The kitchen is being painted this week.","On repeint la cuisine cette semaine.","action en cours"]],"traps":[["The bridge was build in 1900.","The bridge was built in 1900.","Au passif, il faut le participe passé, pas la base."],["My bike has stolen.","My bike has been stolen.","Sans been, la phrase dit que le vélo a volé quelque chose."],["One told me the shop was closed.","I was told the shop was closed.","Le « on » français se rend souvent par un passif."]],"tip":"Be porte le temps, le participe passé porte l'action."},
"cond2":{"intro":"Si tu gagnais au loto, si tu avais plus de temps, si tu étais à la place d'un ami : pour imaginer une situation qui n'est pas réelle, l'anglais a une construction fixe.","parts":[{"h":"La formule","p":"Dans la partie avec if, on met le past simple. Dans l'autre partie, would + base.\n\nC'est très proche du français : « si j'avais » (imparfait), « je voyagerais » (conditionnel).","rows":[["If + past simple","If I had time,","si j'avais le temps"],["would + base","I would travel.","je voyagerais"],["forme courte","I'd travel.","I would devient I'd"],["question","What would you do?","qu'est-ce que tu ferais ?"],["négation","I wouldn't go.","would not"]]},{"h":"Pas de would après if","p":"Comme en français, où on ne dit pas « si j'aurais », l'anglais ne met jamais would juste après if.\n\nIf I had time, pas If I would have time."},{"h":"If I were you","p":"Avec be, la forme soignée est were pour toutes les personnes : If I were you, If she were here.\n\nOn entend aussi If I was you à l'oral, mais If I were you est l'expression la plus courante pour donner un conseil."},{"h":"L'ordre des deux parties","p":"On peut commencer par if ou par l'autre partie. Quand if est en premier, on met une virgule : If I had money, I'd buy a car. Sinon, pas de virgule : I'd buy a car if I had money."}],"ex":[["If I had more time, I would travel more.","Si j'avais plus de temps, je voyagerais plus.",""],["What would you do if you won the lottery?","Qu'est-ce que tu ferais si tu gagnais au loto ?",""],["If I were you, I'd call her.","Si j'étais toi, je l'appellerais.","conseil"],["If it wasn't so expensive, I'd buy it.","Si ce n'était pas si cher, je l'achèterais.",""],["I'd help you if I could.","Je t'aiderais si je pouvais.",""],["If we lived by the sea, we'd swim every day.","Si on habitait au bord de la mer, on nagerait tous les jours.",""],["Would you come if I invited you?","Tu viendrais si je t'invitais ?",""]],"traps":[["If I would have time, I would travel.","If I had time, I would travel.","Après if, on met le past simple, pas would."],["If I have more time, I would travel.","If I had more time, I would travel.","Pour une situation imaginaire, c'est le past simple après if."],["If I were you, I will call him.","If I were you, I would call him.","La deuxième partie prend would, pas will."]],"tip":"Si j'avais, je ferais : If I had, I would, et jamais would après if."},
"cond3":{"intro":"Si tu avais su, tu serais venu ; tu regrettes de ne pas avoir étudié plus. Pour imaginer un passé différent ou dire un regret, l'anglais remonte d'un cran dans le temps.","parts":[{"h":"Le conditionnel passé","p":"Pour imaginer un passé qui ne s'est pas produit : If + had + participe passé, puis would have + participe passé.\n\nC'est le même découpage qu'en français : « si j'avais su » (plus-que-parfait), « je serais venu » (conditionnel passé).","rows":[["If + had + pp","If I had known,","si j'avais su"],["would have + pp","I would have come.","je serais venu"],["formes courtes","If I'd known, I'd have come.","'d = had ou would"],["négation","I wouldn't have gone.","je ne serais pas allé"]]},{"h":"I wish pour un regret","p":"I wish exprime un regret. Pour un regret sur le présent, on met le past simple : I wish I had more time, j'aimerais avoir plus de temps.\n\nPour un regret sur le passé, on recule encore : I wish + had + participe passé. I wish I had studied more : je regrette de ne pas avoir étudié plus.","rows":[["regret présent","I wish I had more time.","past simple"],["regret passé","I wish I had studied more.","had + pp"],["regret passé, négatif","I wish I hadn't said that.","je regrette d'avoir dit ça"]]},{"h":"Le piège du 'd","p":"Dans If I'd known, I'd have come, le premier 'd veut dire had, le second would.\n\nAstuce : devant have, c'est would ; devant un participe passé, c'est had."}],"ex":[["If I had known, I would have come.","Si j'avais su, je serais venu.",""],["I wish I had more time.","J'aimerais avoir plus de temps.","regret présent"],["I wish I'd studied more.","Je regrette de ne pas avoir étudié plus.","regret passé"],["If we had left earlier, we wouldn't have missed the train.","Si on était partis plus tôt, on n'aurait pas raté le train.",""],["I wish I hadn't eaten so much.","Je regrette d'avoir autant mangé.",""],["What would you have done in my place?","Qu'est-ce que tu aurais fait à ma place ?",""],["If she'd asked me, I'd have helped her.","Si elle me l'avait demandé, je l'aurais aidée.",""]],"traps":[["If I would have known, I would have come.","If I had known, I would have come.","Après if, c'est had + participe passé, jamais would."],["I wish I studied more.","I wish I had studied more.","Pour un regret sur le passé, il faut had + participe passé."],["If I had known, I would come.","If I had known, I would have come.","Pour le passé, la deuxième partie prend would have + participe passé."]],"tip":"Pour refaire le passé : had + participe après if et après I wish, would have dans l'autre moitié."},
"usedto":{"intro":"Avant, tu fumais ; maintenant, tu es habitué à te lever tôt. Ces deux idées se disent avec used to en anglais, mais pas de la même façon.","parts":[{"h":"Used to + base : avant, mais plus maintenant","p":"Used to + base parle d'une habitude ou d'une situation passée, qui est terminée. C'est souvent ce que le français dit avec « avant » et l'imparfait.\n\nI used to smoke : avant, je fumais (et j'ai arrêté).","rows":[["affirmation","I used to smoke.","used to + base"],["question","Did you use to smoke?","did + use, sans d"],["négation","I didn't use to smoke.","didn't + use, sans d"]]},{"h":"Sans d après did","p":"Comme après tout did, le verbe revient à sa base : use, sans d. Did you use to play football? et non Did you used to.\n\nÀ l'oral, used to et use to se prononcent pareil, mais à l'écrit, la différence compte."},{"h":"Be used to + -ing : être habitué à","p":"Be used to veut dire être habitué à quelque chose. Ici, to est une préposition : il est suivi d'un nom ou d'un verbe en -ing.\n\nI'm used to getting up early : je suis habitué à me lever tôt. On dit aussi get used to pour s'habituer.","rows":[["used to + base","I used to live in Paris.","habitude passée"],["be used to + -ing","I'm used to living alone.","être habitué à"],["get used to + -ing","You'll get used to it.","s'habituer à"]]}],"ex":[["I used to smoke.","Avant, je fumais.",""],["I'm used to getting up early.","Je suis habitué à me lever tôt.",""],["Did you use to play football when you were a kid?","Tu jouais au foot quand tu étais petit ?","use sans d"],["We used to live in Marseille.","Avant, on habitait à Marseille.",""],["She isn't used to the cold.","Elle n'est pas habituée au froid.","used to + nom"],["I didn't use to like vegetables.","Avant, je n'aimais pas les légumes.",""],["Don't worry, you'll get used to it.","Ne t'inquiète pas, tu vas t'y habituer.",""]],"traps":[["Did you used to play football?","Did you use to play football?","Après did, on écrit use, sans d."],["I'm used to get up early.","I'm used to getting up early.","Après be used to, le verbe prend -ing."],["I use to smoke when I was young.","I used to smoke when I was young.","À l'affirmative, il faut used, avec un d."]],"tip":"Used to + base pour ce qui est fini, be used to + -ing pour ce dont tu as l'habitude."},
"modals":{"intro":"Ton ami n'est pas venu : il a dû oublier. Ta collègue est absente : elle est peut-être malade. Pour faire des déductions, l'anglais utilise must, might et can't.","parts":[{"h":"Trois degrés de certitude","p":"Must veut dire que tu es presque sûr. Might ou may, que c'est possible. Can't, que c'est impossible selon toi.\n\nAprès ces modaux, le verbe reste à la base, sans to.","rows":[["must be","She must be tired.","presque sûr : elle doit être fatiguée"],["might be / may be","She might be sick.","peut-être : elle est peut-être malade"],["can't be","It can't be true.","impossible : ça ne peut pas être vrai"]]},{"h":"Déduire sur le passé","p":"Pour une déduction sur quelque chose de passé, on ajoute have + participe passé après le modal.\n\nHe must have forgotten : il a dû oublier, j'en suis presque sûr.","rows":[["must have + pp","He must have forgotten.","il a dû oublier"],["might have + pp","She might have missed the bus.","elle a peut-être raté le bus"],["can't have + pp","They can't have finished already.","ils ne peuvent pas avoir déjà fini"]]},{"h":"Le contraire de must, c'est can't","p":"Pour une déduction, le contraire de must be n'est pas mustn't be, c'est can't be.\n\nMustn't veut dire « il ne faut pas » : c'est une interdiction, pas une déduction."},{"h":"Le piège de « il a dû »","p":"En français, « il a dû » peut vouloir dire « il a été obligé » ou « il a sans doute ».\n\nPour l'obligation, c'est had to : he had to leave. Pour la déduction, c'est must have : he must have left."}],"ex":[["He must have forgotten.","Il a dû oublier.","déduction"],["She might be sick.","Elle est peut-être malade.",""],["That can't be true.","Ça ne peut pas être vrai.",""],["You must be hungry after that walk.","Tu dois avoir faim après cette balade.",""],["The lights are off, they may be asleep.","Les lumières sont éteintes, ils dorment peut-être.",""],["I can't find my keys, I must have left them at work.","Je ne trouve pas mes clés, j'ai dû les laisser au travail.",""],["He can't have seen us, it was too dark.","Il ne peut pas nous avoir vus, il faisait trop sombre.",""],["She might have missed the train.","Elle a peut-être raté le train.",""]],"traps":[["He must forgot.","He must have forgotten.","Pour le passé, il faut must have + participe passé."],["It mustn't be true.","It can't be true.","Pour une déduction négative, c'est can't, pas mustn't."],["She must to be tired.","She must be tired.","Après un modal, pas de to."]],"tip":"Must pour le presque sûr, might pour le peut-être, can't pour l'impossible, et have + participe pour le passé."},
"reported":{"intro":"Tu racontes à un ami ce qu'un collègue t'a dit hier : c'est le discours rapporté. En anglais, comme en français, les temps reculent d'un cran.","parts":[{"h":"Le principe : reculer d'un temps","p":"Quand le verbe d'introduction est au passé (said, told), le verbe rapporté recule d'un temps. C'est la même logique qu'en français : « je suis fatigué » devient « il a dit qu'il était fatigué ».\n\nLe mot that est facultatif : He said (that) he was tired.","rows":[["is / am / are devient was / were","I'm tired. He said he was tired.",""],["présent simple devient prétérit","I live here. She said she lived there.",""],["will devient would","I'll come. He said he would come.",""],["can devient could","I can help. She said she could help.",""],["prétérit ou present perfect devient past perfect","I've finished. He said he had finished.","à l'oral, le prétérit reste souvent tel quel"]]},{"h":"say ou tell ?","p":"tell veut toujours une personne juste après : He told me… On ne dit pas « He said me ».\n\nsay s'emploie sans personne : He said he was tired. Si tu veux nommer la personne avec say, il faut to : He said to me…","rows":[["tell + personne","She told me she was busy.",""],["say + phrase","She said she was busy.",""],["say to + personne","She said to me that she was busy.","plus rare"]]},{"h":"Les questions rapportées","p":"Dans une question rapportée, il n'y a plus d'inversion : on revient à l'ordre sujet + verbe. « Où habites-tu ? » devient She asked me where I lived, et non « where did I live ».\n\nPour une question à laquelle on répond par oui ou non, on ajoute if ou whether : He asked if I was ready.","rows":[["Where do you live?","She asked me where I lived.","plus de do, plus d'inversion"],["Are you ready?","He asked if I was ready.","if = si"],["What time is it?","I asked what time it was.",""]]},{"h":"Les repères de temps et de lieu","p":"Comme tu racontes plus tard, les mots qui situent changent aussi : tomorrow devient the next day, yesterday devient the day before, here devient there.\n\nSi l'information est toujours vraie au moment où tu parles, tu peux garder le présent : He said he lives in Lyon (il y vit toujours)."}],"ex":[["She told me she was moving to Bristol.","Elle m'a dit qu'elle déménageait à Bristol.",""],["He said he would call me back.","Il a dit qu'il me rappellerait.","will devient would"],["My boss asked me why I was late.","Mon patron m'a demandé pourquoi j'étais en retard.","pas d'inversion"],["They said they had already eaten.","Ils ont dit qu'ils avaient déjà mangé.",""],["She asked if I could help her the next day.","Elle m'a demandé si je pouvais l'aider le lendemain.","tomorrow devient the next day"],["I asked him where the station was.","Je lui ai demandé où était la gare.",""],["He told us he couldn't come.","Il nous a dit qu'il ne pouvait pas venir.",""]],"traps":[["He said me he was tired.","He told me he was tired.","tell prend la personne directement, say non."],["She asked me where did I live.","She asked me where I lived.","Dans une question rapportée, ni do ni inversion."],["He said he will come.","He said he would come.","Après said, will recule en would."]],"tip":"Je raconte plus tard, donc je recule d'un temps, et ma question redevient une phrase normale."},
"pastperf":{"intro":"Tu arrives au cinéma et le film a déjà commencé : deux actions passées, l'une avant l'autre. Le past perfect sert à marquer celle qui est arrivée en premier.","parts":[{"h":"La forme : had + participe passé","p":"C'est le plus-que-parfait du français (j'avais vu, elle était partie). Une seule forme pour tout le monde : had, puis le participe passé.\n\nÀ l'oral, had se contracte : I'd, she'd, they'd.","rows":[["affirmation","She had left.","Elle était partie."],["contraction","She'd left.",""],["négation","She hadn't left.","had not"],["question","Had she left?","Elle était partie ?"]]},{"h":"Quand l'employer","p":"Tu racontes au prétérit. Quand tu dois remonter encore plus loin en arrière, tu passes au past perfect : When I arrived, the film had already started. Le film a commencé d'abord.\n\nCompare avec When I arrived, the film started : là, le film commence au moment où tu arrives.","rows":[["When I arrived, the film started.","j'arrive, puis le film commence","deux actions qui se suivent"],["When I arrived, the film had started.","le film avait commencé avant","l'ordre est inversé"]]},{"h":"Les petits mots qui l'accompagnent","p":"already, never, just, before et by the time reviennent souvent : I had never seen the sea before. By the time we got there, the shop had closed.\n\nAvec after ou before, l'ordre est déjà clair, alors le prétérit suffit souvent : After he left, I went to bed."},{"h":"Attention au « être » du français","p":"En français, certains verbes prennent « être » : elle était partie, il était arrivé. En anglais, c'est toujours had : she had left, he had arrived. Jamais « she was left »."}],"ex":[["When I got home, my flatmate had eaten all the pizza.","Quand je suis rentré, mon colocataire avait mangé toute la pizza.",""],["I had never seen snow before that winter.","Je n'avais jamais vu de neige avant cet hiver-là.",""],["By the time we arrived, the shop had closed.","Le temps qu'on arrive, le magasin avait fermé.","by the time = le temps que"],["She was upset because she had lost her keys.","Elle était contrariée parce qu'elle avait perdu ses clés.",""],["Had you met him before the party?","Tu l'avais déjà rencontré avant la fête ?",""],["They hadn't booked, so there was no table for them.","Ils n'avaient pas réservé, donc il n'y avait pas de table pour eux.",""],["He'd just left when I called.","Il venait de partir quand j'ai appelé.","had just = venait de"]],"traps":[["When I arrived, she was already left.","When I arrived, she had already left.","Le past perfect se fait toujours avec had, même quand le français dit « était »."],["I have never seen the sea before that trip.","I had never seen the sea before that trip.","Le repère est dans le passé, donc had, pas have."]],"tip":"Dans un récit au passé, had te fait remonter d'une marche de plus."},
"tobe":{"intro":"Pour te présenter, dire ton métier ou comment tu vas, tu as besoin du verbe « être ». En anglais, c'est to be.","parts":[{"h":"La conjugaison","p":"Au présent, be a trois formes : am, is, are. On choisit selon le sujet.","rows":[["I am","I am French.","je suis"],["you are","You are nice.","tu es, vous êtes"],["he / she / it is","She is a teacher.","il est, elle est"],["we are","We are at home.","nous sommes"],["they are","They are friends.","ils sont, elles sont"]]},{"h":"Les contractions et la négation","p":"À l'oral et dans les messages, on raccourcit presque toujours. C'est plus naturel.\n\nPour dire non, on ajoute not : I'm not tired, she isn't here, they aren't ready.","rows":[["I'm","I'm tired.",""],["you're / we're / they're","We're late.",""],["he's / she's / it's","It's cold.",""],["isn't / aren't","He isn't here.","négation"],["I'm not","I'm not ready.","jamais « I amn't »"]]},{"h":"Poser une question","p":"Pour poser une question, le verbe passe devant le sujet : You are French devient Are you French, avec un point d'interrogation.\n\nPour répondre court, on reprend juste le verbe : Yes, I am. No, I'm not.","rows":[["Are you French?","Yes, I am.","Tu es français ?"],["Is she here?","No, she isn't.","Elle est là ?"],["Are they ready?","Yes, they are.","Ils sont prêts ?"]]},{"h":"Là où le français dit « avoir »","p":"Certaines idées se disent avec « avoir » en français, mais avec be en anglais : l'âge, la faim, le froid. J'ai 20 ans = I'm 20. J'ai faim = I'm hungry.","rows":[["I'm 25.","J'ai 25 ans.","jamais « I have 25 »"],["I'm hungry.","J'ai faim.",""],["I'm cold.","J'ai froid.",""]]}],"ex":[["I'm Léa and I'm from Lyon.","Je suis Léa et je viens de Lyon.","from = de (l'origine)"],["My brother is a nurse.","Mon frère est infirmier.",""],["We're at the station.","Nous sommes à la gare.",""],["Are you tired?","Tu es fatigué ?",""],["It isn't expensive.","Ce n'est pas cher.",""],["They're my neighbours.","Ce sont mes voisins.","neighbours : orthographe britannique"],["Is your sister at home?","Ta sœur est à la maison ?",""],["I'm thirty.","J'ai trente ans.","l'âge se dit avec be"]],"traps":[["I have 20 years.","I'm 20.","L'âge se dit avec be en anglais."],["She are a teacher.","She is a teacher.","Avec he, she et it, c'est toujours is."],["You are French?","Are you French?","Dans une question, are passe devant le sujet."]],"tip":"I am, you are, he is : et pour l'âge, la faim ou le froid, c'est aussi be."},
"havegot":{"intro":"Pour parler de ta famille, de ton chien ou de ta voiture, tu dis « j'ai ». En anglais, c'est have, ou have got au Royaume-Uni.","parts":[{"h":"have : attention à he, she, it","p":"have se conjugue comme un verbe normal, sauf avec he, she et it : il devient has. Pas « haves ».","rows":[["I / you / we / they have","I have a dog.",""],["he / she / it has","She has two kids.","has, jamais « haves »"]]},{"h":"have got, la version britannique","p":"Au Royaume-Uni, on dit très souvent have got pour ce qu'on possède. Le sens est exactement le même.\n\nÀ l'oral, on contracte : I've got, she's got. Ici, she's veut dire she has, pas she is.","rows":[["I've got","I've got a car.","I have got"],["she's got","She's got a brother.","she has got"],["haven't got","We haven't got time.","négation"]]},{"h":"Questions et négations","p":"Avec have, on utilise do ou does, comme pour les autres verbes. Avec have got, on inverse have et le sujet.\n\nLes deux sont corrects, mais ne les mélange pas dans la même phrase.","rows":[["Do you have a car?","No, I don't.","avec have"],["Have you got a car?","No, I haven't.","avec have got"],["Does she have kids?","Yes, she does.","après does : have, pas has"],["I don't have a car.","I haven't got a car.","deux négations possibles"]]},{"h":"have got, seulement pour posséder","p":"have got sert à dire ce que tu as : un objet, un frère, un rhume. Pour une action, comme prendre un repas ou une douche, on garde have tout seul : I have breakfast at eight. Jamais « I've got breakfast »."}],"ex":[["I have a cat and two fish.","J'ai un chat et deux poissons.",""],["My sister has a new job.","Ma sœur a un nouveau travail.",""],["We've got a small garden.","On a un petit jardin.","britannique"],["Do you have a pen?","Tu as un stylo ?",""],["He hasn't got a car.","Il n'a pas de voiture.",""],["Does your flat have a balcony?","Ton appartement a un balcon ?",""],["I've got a cold.","J'ai un rhume.",""],["They don't have time today.","Ils n'ont pas le temps aujourd'hui.",""]],"traps":[["She have a dog.","She has a dog.","Avec he, she et it, have devient has."],["Does she has a car?","Does she have a car?","Après does, le verbe revient à have."],["Have you a car?","Do you have a car?","Sans got, la question se fait avec do."]],"tip":"She has, mais does she have : le s ne se met jamais à deux endroits."},
"articles":{"intro":"Une pomme, un taxi, le soleil : les petits mots a, an et the sont partout. Bonne nouvelle, ils ne changent ni au masculin ni au féminin.","parts":[{"h":"a ou an : c'est le son qui compte","p":"a et an veulent dire un ou une. On choisit selon le son du mot qui suit, pas selon la lettre.\n\nan devant un son voyelle, a devant un son consonne. Le h muet de hour donne an hour. Le u de university se prononce « you », donc a university.","rows":[["a + son consonne","a car, a book",""],["an + son voyelle","an apple, an egg",""],["an + h muet","an hour","le h ne se prononce pas"],["a + son « you »","a university, a uniform","le u se dit « you »"]]},{"h":"the : une chose précise","p":"the veut dire le, la ou les, et ne change jamais. On l'utilise pour une chose précise, déjà connue ou unique : the sun, the door, the key of my flat."},{"h":"Un métier prend a ou an","p":"En français, on dit « il est ingénieur », sans article. En anglais, il faut a ou an : he's an engineer, she's a doctor."},{"h":"En général : pas d'article","p":"Pour parler d'une chose en général, l'anglais ne met pas d'article. J'aime le café = I like coffee. Les chiens sont gentils = Dogs are friendly.\n\nOn met the seulement pour une chose précise : The coffee in this café is great.","rows":[["en général","I like coffee.","J'aime le café."],["en général, au pluriel","Dogs are friendly.","Les chiens sont gentils."],["chose précise","The coffee is cold.","Le café (celui-ci) est froid."]]}],"ex":[["I'd like an orange juice, please.","Je voudrais un jus d'orange, s'il vous plaît.",""],["She's a nurse.","Elle est infirmière.","un métier : a ou an"],["We waited for an hour.","On a attendu une heure.","h muet : an"],["The bus is late again.","Le bus est encore en retard.",""],["I don't like tea.","Je n'aime pas le thé.","en général : pas d'article"],["He's an actor.","Il est acteur.",""],["Close the window, please.","Ferme la fenêtre, s'il te plaît.",""],["It's a nice day.","C'est une belle journée.",""]],"traps":[["He's engineer.","He's an engineer.","Un métier prend toujours a ou an."],["I like the coffee.","I like coffee.","Pour parler en général, pas d'article."],["a hour","an hour","Le h de hour ne se prononce pas : on entend une voyelle."]],"tip":"Écoute le mot : un son voyelle appelle an, et ce qui est « en général » se passe d'article."},
"plurals":{"intro":"Trois enfants, ces chaussures, les gens : pour parler de plusieurs choses, il faut le pluriel et les bons petits mots pour montrer.","parts":[{"h":"Le pluriel régulier : -s","p":"La plupart des mots prennent un -s : a car, two cars. Après s, sh, ch ou x, on ajoute -es : a bus, two buses.\n\nUn y après une consonne devient -ies : a city, two cities.","rows":[["+ s","car, cars",""],["+ es","bus, buses ; watch, watches","après s, sh, ch, x"],["y devient ies","city, cities","mais day, days"]]},{"h":"Les pluriels irréguliers","p":"Quelques mots très courants ne prennent pas de -s. Il faut les apprendre par cœur.","rows":[["child, children","three children","enfant"],["person, people","two people","personne"],["man, men","five men","homme"],["woman, women","two women","femme"],["foot, feet","my feet","pied"],["tooth, teeth","my teeth","dent"]]},{"h":"this, that, these, those","p":"this et that montrent une seule chose, these et those en montrent plusieurs. this et these pour ce qui est près de toi, that et those pour ce qui est plus loin.","rows":[["this","this shoe","près, singulier"],["these","these shoes","près, pluriel"],["that","that house","loin, singulier"],["those","those houses","loin, pluriel"]]},{"h":"people est déjà pluriel","p":"En français, « les gens » est pluriel, et c'est pareil en anglais : people are. On n'ajoute pas de -s pour dire les gens.\n\nPour une seule personne, on dit a person. Et pour parler des gens en général, pas besoin de the : People are nice here."}],"ex":[["These apples are delicious.","Ces pommes sont délicieuses.",""],["My children are at school.","Mes enfants sont à l'école.",""],["Those people are very loud.","Ces gens-là sont très bruyants.","those : plus loin"],["I need two boxes.","J'ai besoin de deux boîtes.","box, boxes"],["Is this your bag?","C'est ton sac ?","this : tout près"],["There are three women in my team.","Il y a trois femmes dans mon équipe.",""],["My feet are cold.","J'ai froid aux pieds.","foot, feet"]],"traps":[["People is nice here.","People are nice here.","people est pluriel : le verbe est are."],["This shoes are new.","These shoes are new.","Au pluriel, this devient these."],["three childs","three children","child a un pluriel irrégulier."]],"tip":"Un child, des children ; une chose, this ; plusieurs, these."},
"thereis":{"intro":"En ville, tu cherches une banque ou un café. Pour dire « il y a », l'anglais utilise there is et there are.","parts":[{"h":"Singulier ou pluriel","p":"there is avec une seule chose, there are avec plusieurs. À l'oral, there is se contracte souvent en there's.","rows":[["there is / there's","There's a bank.","une seule chose"],["there are","There are two cafés.","plusieurs choses"],["there isn't","There isn't a bus.","négation, singulier"],["there aren't","There aren't any shops.","négation, pluriel"]]},{"h":"Poser la question","p":"On inverse : is ou are passe devant there. On répond court : Yes, there is. No, there aren't.","rows":[["Is there a bus?","Yes, there is.","Est-ce qu'il y a un bus ?"],["Are there any shops?","No, there aren't.","Est-ce qu'il y a des magasins ?"]]},{"h":"Jamais « it has »","p":"En français, « il y a » contient « a », alors on est tenté de dire it has. C'est faux : it has veut dire « il a », au sens de posséder.\n\nPour dire qu'une chose existe quelque part, c'est toujours there is ou there are."}],"ex":[["There's a pharmacy next to the bakery.","Il y a une pharmacie à côté de la boulangerie.",""],["There are four people in my family.","Il y a quatre personnes dans ma famille.",""],["Is there a lift in the building?","Est-ce qu'il y a un ascenseur dans l'immeuble ?","lift au Royaume-Uni, elevator aux États-Unis"],["There isn't any milk in the fridge.","Il n'y a pas de lait dans le frigo.",""],["Are there any good restaurants near here?","Il y a de bons restaurants près d'ici ?",""],["There's a problem with my phone.","Il y a un problème avec mon téléphone.",""],["There are a lot of tourists in summer.","Il y a beaucoup de touristes en été.","a lot of + pluriel : are"]],"traps":[["It has a bank near here.","There's a bank near here.","it has veut dire « il possède », pas « il y a »."],["There is two cafés.","There are two cafés.","Avec un pluriel, c'est there are."],["There is a bus?","Is there a bus?","Dans une question, is passe devant there."]],"tip":"Il y a = there is pour un, there are pour plusieurs, et jamais it has."},
"can":{"intro":"Savoir nager, pouvoir venir, demander de l'aide : en anglais, un seul petit mot fait tout ça, can.","parts":[{"h":"La forme : can + verbe","p":"can ne change jamais : I can, she can, they can. Pas de -s avec he, she ou it.\n\nAprès can, le verbe est à la base, sans to : I can swim, et non « I can to swim ».","rows":[["I / you / we / they can","I can drive.",""],["he / she / it can","She can drive.","pas de -s"],["can't / cannot","He can't come.","négation"],["Can you…?","Can you help me?","question"]]},{"h":"Pouvoir, savoir, avoir le droit","p":"can couvre trois idées que le français sépare : la capacité (je sais nager), la possibilité (je peux venir) et la permission (tu peux t'asseoir).\n\nDonc « je sais nager » se dit I can swim. On n'utilise pas know pour une compétence.","rows":[["capacité","I can swim.","Je sais nager."],["possibilité","I can come tomorrow.","Je peux venir demain."],["permission","You can sit here.","Tu peux t'asseoir ici."]]},{"h":"Questions et réponses courtes","p":"Pour poser une question, can passe devant le sujet. Pour répondre, on reprend juste can : Yes, I can. No, I can't.","rows":[["Can she speak Spanish?","Yes, she can.","Elle parle espagnol ?"],["Can I open the window?","Of course.","Je peux ouvrir la fenêtre ?"]]}],"ex":[["I can play the guitar.","Je sais jouer de la guitare.",""],["Can you speak more slowly, please?","Tu peux parler plus lentement, s'il te plaît ?",""],["She can't come tonight.","Elle ne peut pas venir ce soir.",""],["Can I pay by card?","Je peux payer par carte ?",""],["My son can read now.","Mon fils sait lire maintenant.",""],["We can meet at six.","On peut se retrouver à six heures.",""],["I can't find my keys.","Je ne trouve pas mes clés.","can't find : très courant pour « je ne trouve pas »"]],"traps":[["I can to swim.","I can swim.","Après can, pas de to."],["She cans drive.","She can drive.","can ne prend jamais de -s."],["I know swim.","I can swim.","Savoir faire quelque chose se dit avec can."]],"tip":"can ne bouge pas : pas de to après, pas de s, et il veut aussi dire « savoir faire »."},
"compar":{"intro":"Le train ou le bus ? Cet hôtel ou l'autre ? Pour comparer et choisir, tu as besoin du comparatif et du superlatif.","parts":[{"h":"Mots courts : -er et -est","p":"Avec un adjectif court (une syllabe, ou deux syllabes finissant par -y), on ajoute -er pour comparer et the -est pour dire « le plus ».\n\nAttention à l'orthographe : big donne bigger, easy donne easier.","rows":[["fast","faster than, the fastest",""],["cheap","cheaper than, the cheapest",""],["big","bigger than, the biggest","la consonne est doublée"],["easy","easier than, the easiest","le y devient i"]]},{"h":"Mots longs : more et the most","p":"Avec un adjectif long (deux syllabes ou plus, sauf ceux en -y), on ne touche pas au mot. On met more devant pour comparer, the most pour le superlatif.","rows":[["expensive","more expensive than, the most expensive",""],["interesting","more interesting than, the most interesting",""],["comfortable","more comfortable than, the most comfortable",""]]},{"h":"Les irréguliers","p":"Trois adjectifs très courants changent complètement. Ce sont aussi ceux qu'on utilise le plus.","rows":[["good","better than, the best","bon, meilleur, le meilleur"],["bad","worse than, the worst","mauvais, pire, le pire"],["far","further than, the furthest","loin, plus loin, le plus loin"]]},{"h":"than, in et les pièges du français","p":"« que » se dit than après un comparatif : faster than the bus.\n\nAprès un superlatif, le « de » français devient souvent in devant un lieu ou un groupe : the best restaurant in town, the tallest in my family."}],"ex":[["My flat is smaller than yours.","Mon appartement est plus petit que le tien.",""],["This phone is more expensive than the other one.","Ce téléphone est plus cher que l'autre.",""],["It's the best pizza in Paris.","C'est la meilleure pizza de Paris.","de devient in"],["Today is hotter than yesterday.","Aujourd'hui, il fait plus chaud qu'hier.","hot, hotter"],["She's the youngest in the class.","C'est la plus jeune de la classe.",""],["The film was worse than the book.","Le film était pire que le livre.",""],["This is the most beautiful beach I know.","C'est la plus belle plage que je connaisse.",""],["English is easier than Chinese.","L'anglais est plus facile que le chinois.",""]],"traps":[["The train is more fast than the bus.","The train is faster than the bus.","Un adjectif court prend -er, pas more."],["This one is more good.","This one is better.","good est irrégulier : better, the best."],["the best restaurant of the city","the best restaurant in the city","Après un superlatif, un lieu se dit avec in."]],"tip":"Court, j'ajoute -er ; long, je mets more devant ; et good et bad n'en font qu'à leur tête."},
"someany":{"intro":"Pour faire les courses, cuisiner ou demander du lait, tu dois dire « du », « des » ou « combien ». C'est le rôle de some, any, much et many.","parts":[{"h":"some et any","p":"some veut dire du, de la, des ou quelques, dans une phrase affirmative.\n\nany prend sa place dans les questions et les négations. Petite exception : quand tu proposes quelque chose, tu gardes some.","rows":[["affirmation : some","I bought some bread.","du pain"],["question : any","Is there any milk?","du lait ?"],["négation : any","We don't have any eggs.","pas d'œufs"],["offre : some","Would you like some tea?","on propose, donc some"]]},{"h":"Ce qui se compte, ce qui ne se compte pas","p":"Un nom dénombrable se compte : one apple, two apples. Un nom indénombrable ne se compte pas : milk, time, money, water.\n\nCette différence décide entre much et many.","rows":[["dénombrable","apples, people, friends","se met au pluriel"],["indénombrable","milk, time, money, information","pas de pluriel"]]},{"h":"much, many, how much, how many","p":"many va avec ce qui se compte, much avec ce qui ne se compte pas. On les utilise surtout dans les questions et les négations. Dans une phrase affirmative, a lot of sonne plus naturel.\n\nCombien se dit how many devant un pluriel, how much devant un indénombrable, et aussi pour un prix.","rows":[["many + dénombrable","not many people","pas beaucoup de gens"],["much + indénombrable","not much time","pas beaucoup de temps"],["how many","How many people?","combien de personnes"],["how much","How much is it?","combien ça coûte"]]}],"ex":[["I need some help.","J'ai besoin d'aide.",""],["Are there any tickets left?","Il reste des billets ?",""],["She doesn't have many friends here.","Elle n'a pas beaucoup d'amis ici.",""],["How much water do you drink?","Tu bois combien d'eau ?","water ne se compte pas"],["We didn't buy any vegetables.","On n'a pas acheté de légumes.",""],["How many brothers have you got?","Tu as combien de frères ?",""],["There's some cake in the kitchen.","Il y a du gâteau dans la cuisine.",""],["I don't have much money this month.","Je n'ai pas beaucoup d'argent ce mois-ci.",""]],"traps":[["Is there some milk?","Is there any milk?","Dans une question simple, on utilise any."],["How much people?","How many people?","people se compte, donc many."],["I don't have some time.","I don't have any time.","Dans une négation, some devient any."]],"tip":"some quand j'affirme, any quand je demande ou je nie ; many se compte, much non."},
"inversion":{"intro":"Dans un discours, un article ou une lettre soignée, tu veux frapper fort : « Jamais je n'ai vu ça ». L'anglais soutenu inverse alors le sujet et l'auxiliaire.","parts":[{"h":"Le mécanisme","p":"Quand un mot négatif ou restrictif ouvre la phrase, on prend l'ordre d'une question : auxiliaire, puis sujet, puis verbe.\n\nI have never seen such a mess devient Never have I seen such a mess. Le sens ne change pas, seul le ton monte.","rows":[["Never","Never have I seen such a mess.","jamais"],["Rarely / Seldom","Rarely do we get such offers.","rarement"],["Not only… but also","Not only is he late, but he has also forgotten.","non seulement… mais aussi"],["Hardly… when","Hardly had I arrived when the phone rang.","à peine… que"],["No sooner… than","No sooner had she left than it started to rain.","à peine… que"]]},{"h":"Le retour de do","p":"S'il n'y a pas d'auxiliaire, on fait comme dans une question : on ajoute do, does ou did. We rarely go out devient Rarely do we go out.\n\nAvec be, on inverse directement : Not only is he late…","rows":[["We rarely see him.","Rarely do we see him.","présent : do"],["She seldom complained.","Seldom did she complain.","passé : did, puis la base"],["He is late.","Not only is he late…","be s'inverse seul"]]},{"h":"Hardly et No sooner : juste avant","p":"Hardly et No sooner décrivent deux actions qui se suivent de très près. La première est au past perfect, inversée : Hardly had I arrived.\n\nAttention au mot qui suit : Hardly va avec when, No sooner va avec than."},{"h":"Quand l'utiliser","p":"C'est un registre soutenu : discours, écrits formels, récits. Au quotidien, on garde l'ordre normal : I've never seen such a mess.\n\nL'inversion ne touche que la partie qui suit le mot négatif. Dans Not only… but also, la deuxième moitié reste dans l'ordre normal."}],"ex":[["Never have I felt so welcome in a new city.","Jamais je ne me suis senti aussi bien accueilli dans une nouvelle ville.",""],["Rarely do we see such talent in young players.","On voit rarement un tel talent chez de jeunes joueurs.",""],["Not only did she finish the report, but she also checked every figure.","Non seulement elle a fini le rapport, mais elle a aussi vérifié chaque chiffre.","did, puis la base"],["Hardly had we sat down when the fire alarm went off.","À peine nous étions-nous assis que l'alarme incendie s'est déclenchée.",""],["No sooner had he paid than he realised his mistake.","À peine avait-il payé qu'il s'est rendu compte de son erreur.","No sooner va avec than"],["Seldom has the company faced such a crisis.","Rarement l'entreprise a-t-elle connu une telle crise.",""],["Under no circumstances should you share your password.","Tu ne dois en aucun cas communiquer ton mot de passe.","under no circumstances = en aucun cas"]],"traps":[["Never I have seen such a mess.","Never have I seen such a mess.","Après Never en tête, l'auxiliaire passe devant le sujet."],["Rarely we go out.","Rarely do we go out.","Sans auxiliaire, on ajoute do comme dans une question."],["Hardly had I arrived than the phone rang.","Hardly had I arrived when the phone rang.","Hardly va avec when ; than va avec No sooner."]],"tip":"Mot négatif en tête, et la phrase prend l'ordre d'une question."},
"mixedcond":{"intro":"« Si j'avais accepté ce poste, je vivrais à Londres aujourd'hui » : un choix passé, une conséquence présente. Les conditionnels mixtes croisent les deux époques.","parts":[{"h":"Rappel des deux briques","p":"Le conditionnel 2 parle d'un présent imaginaire : If I were rich, I would travel. Le conditionnel 3 parle d'un passé imaginaire : If I had known, I would have come.\n\nUn conditionnel mixte prend une moitié de chacun.","rows":[["présent imaginaire","If I were rich, I'd travel.","if + prétérit, would + base"],["passé imaginaire","If I'd known, I'd have come.","if + past perfect, would have + participe"]]},{"h":"Du passé vers le présent","p":"C'est le cas le plus courant. La condition porte sur le passé (if + past perfect), le résultat sur aujourd'hui (would + base). On trouve souvent now ou today.\n\nIf I had taken the job, I would live in London now : je ne l'ai pas pris, et je ne vis pas à Londres."},{"h":"Du présent vers le passé","p":"L'inverse existe aussi : un trait permanent explique un fait passé. La condition est au prétérit (if he were), le résultat au conditionnel passé (would have + participe).\n\nIf he were more organised, he wouldn't have missed the train : il n'est pas organisé en général, donc il a raté le train."},{"h":"Le français fait pareil","p":"Le français mélange exactement de la même façon : si j'avais pris (plus-que-parfait), je vivrais (conditionnel présent). Ton instinct français est un bon guide pour choisir les temps.\n\nLe seul piège : jamais de would dans la partie avec if. Après if, were est plus soutenu que was.","rows":[["si + plus-que-parfait","if + past perfect","si j'avais su"],["conditionnel présent","would + base","je serais"],["conditionnel passé","would have + participe","j'aurais été"]]}],"ex":[["If I had studied medicine, I would be a doctor now.","Si j'avais fait médecine, je serais médecin aujourd'hui.","passé vers présent"],["If we'd left earlier, we'd be there by now.","Si on était partis plus tôt, on y serait déjà.",""],["If she wasn't so shy, she would have spoken to him.","Si elle n'était pas aussi timide, elle lui aurait parlé.","présent vers passé"],["If I hadn't met you, my life would be very different.","Si je ne t'avais pas rencontré, ma vie serait très différente.",""],["If he spoke German, he would have got the job.","S'il parlait allemand, il aurait eu le poste.",""],["If you had listened to me, we wouldn't be lost.","Si tu m'avais écouté, on ne serait pas perdus.",""],["If I weren't afraid of flying, I'd have visited you last year.","Si je n'avais pas peur de l'avion, je serais venu te voir l'année dernière.",""]],"traps":[["If I would have taken the job, I would live in London now.","If I had taken the job, I would live in London now.","Jamais de would dans la partie avec if."],["If I had taken the job, I would have lived in London now.","If I had taken the job, I would live in London now.","Avec now, le résultat est présent : would + base."]],"tip":"Chaque moitié garde son époque : le passé avec had, le présent avec would + base."},
"rather":{"intro":"Exprimer une préférence polie ou un regret : « je préférerais que tu ne fumes pas », « si seulement il arrêtait de pleuvoir ». L'anglais emploie alors le prétérit pour parler du présent.","parts":[{"h":"would rather","p":"I'd rather + base, quand c'est toi qui agis : I'd rather stay home (je préfère rester).\n\nI'd rather + quelqu'un + prétérit, quand c'est un autre : I'd rather you didn't smoke here. Le prétérit ne parle pas du passé ici : il marque le souhait, comme le subjonctif en français.","rows":[["I'd rather + base","I'd rather walk.","je préfère marcher"],["I'd rather + sujet + prétérit","I'd rather you stayed.","je préférerais que tu restes"],["négation","I'd rather you didn't.","je préférerais que tu évites"],["… than…","I'd rather walk than wait.","plutôt que"]]},{"h":"wish et if only + prétérit","p":"wish et if only suivis du prétérit expriment le regret d'une situation présente : I wish you were here (tu n'es pas là). If only I had more time (je n'en ai pas).\n\nAvec be, le registre soigné utilise were pour tout le monde : I wish I were taller.","rows":[["wish + prétérit","I wish you were here.","situation présente"],["if only + prétérit","If only I knew the answer.","situation présente"],["wish + past perfect","I wish I hadn't said that.","regret sur le passé"]]},{"h":"wish et if only + would","p":"Avec would, tu veux que quelqu'un ou quelque chose change, souvent avec agacement. If only it would stop raining veut dire que la pluie t'agace et que tu voudrais qu'elle cesse.\n\nPour toi-même, on ne dit pas « I wish I would » : on utilise could ou le prétérit.","rows":[["I wish you would listen.","J'aimerais que tu écoutes.","agacement"],["If only it would stop raining!","Si seulement il arrêtait de pleuvoir !",""],["I wish I could come.","J'aimerais pouvoir venir.","jamais « I wish I would »"]]}],"ex":[["I'd rather have tea, if you don't mind.","Je prendrais plutôt du thé, si ça ne te dérange pas.",""],["I'd rather you didn't tell anyone.","Je préférerais que tu n'en parles à personne.",""],["I wish I lived closer to the sea.","J'aimerais habiter plus près de la mer.",""],["If only I had known earlier!","Si seulement je l'avais su plus tôt !","regret sur le passé"],["I wish he would stop interrupting me.","J'aimerais qu'il arrête de me couper la parole.",""],["Would you rather go out or stay in tonight?","Tu préfères sortir ou rester à la maison ce soir ?",""],["If only the neighbours would turn the music down!","Si seulement les voisins baissaient la musique !",""]],"traps":[["I'd rather you don't smoke here.","I'd rather you didn't smoke here.","Après I'd rather + quelqu'un, le verbe passe au prétérit."],["I wish you are here.","I wish you were here.","wish sur une situation présente appelle le prétérit."],["I'd rather to stay home.","I'd rather stay home.","Après would rather, pas de to."]],"tip":"Pour souhaiter un autre présent, l'anglais recule au prétérit."},
"cleft":{"intro":"Pour corriger quelqu'un ou insister sur l'essentiel, le français dit « c'est… qui » ou « ce dont j'ai besoin, c'est… ». L'anglais a exactement les mêmes outils.","parts":[{"h":"What… is : l'essentiel à la fin","p":"On commence par What + sujet + verbe, puis is, puis ce sur quoi on insiste. I need sleep devient What I need is sleep.\n\nSi la suite est une action, on met souvent la base verbale : What I did was call the police.","rows":[["What I need is…","What I need is a holiday.","ce dont j'ai besoin"],["What I like is…","What I like is the silence.","ce que j'aime"],["What she said was…","What she said was true.","ce qu'elle a dit"],["What you should do is…","What you should do is call him.","action : base verbale"]]},{"h":"It is / was… who / that","p":"Pour isoler un élément, on l'encadre : It was Marie who called. C'est l'équivalent exact de « c'est Marie qui a appelé ».\n\nwho pour une personne, that pour tout le reste (that marche aussi pour une personne).","rows":[["It was Marie who called.","C'est Marie qui a appelé.","personne : who ou that"],["It's the price that worries me.","C'est le prix qui m'inquiète.","chose : that"],["It was in 2019 that we met.","C'est en 2019 qu'on s'est rencontrés.","une date"]]},{"h":"Les pièges du français","p":"En français, on dit « c'est » même au passé. En anglais, be suit le temps du récit : « C'est Marie qui a appelé » se dit It was Marie who called.\n\nEn tête de phrase, « ce que » ou « ce dont » se dit what. Mais après un nom, on utilise that : the thing that I need."}],"ex":[["What I love about this city is the food.","Ce que j'adore dans cette ville, c'est la cuisine.",""],["It was my brother who broke the window, not me.","C'est mon frère qui a cassé la vitre, pas moi.",""],["What surprised me was his reaction.","Ce qui m'a surpris, c'est sa réaction.",""],["It's the noise that I can't stand.","C'est le bruit que je ne supporte pas.",""],["What you need is a good night's sleep.","Ce qu'il te faut, c'est une bonne nuit de sommeil.",""],["It was only last week that I found out.","C'est seulement la semaine dernière que je l'ai appris.",""],["What we did was cancel the trip.","Ce qu'on a fait, c'est annuler le voyage.","action : base verbale"]],"traps":[["It is Marie who called yesterday.","It was Marie who called yesterday.","Au passé, on dit it was."],["That I need is sleep.","What I need is sleep.","« Ce dont » ou « ce que » en tête se dit what."],["The thing what I need is sleep.","The thing that I need is sleep.","Après un nom, c'est that, jamais what."]],"tip":"Pour insister, encadre : What… is devant l'essentiel, It was… who autour de la personne."},
"linkers":{"intro":"Dans un mail, un débat ou une rédaction, tu opposes deux idées : malgré, bien que, alors que. Chaque mot anglais impose sa construction.","parts":[{"h":"despite et in spite of + nom ou -ing","p":"despite et in spite of veulent dire malgré. Ils sont suivis d'un nom ou d'un verbe en -ing, jamais d'une phrase complète.\n\ndespite s'emploie seul, in spite of garde son of. Jamais « despite of ».","rows":[["despite + nom","despite the rain","malgré la pluie"],["in spite of + -ing","in spite of being tired","bien qu'il soit fatigué"],["despite the fact that + phrase","despite the fact that it rained","pour garder une phrase"]]},{"h":"although et even though + phrase","p":"although et even though veulent dire bien que ou même si. Ils sont suivis d'une phrase complète, avec sujet et verbe.\n\neven though est plus fort : il souligne la surprise. Pas de subjonctif en anglais, un temps normal suffit.","rows":[["although + phrase","Although he's tired, he keeps going.","bien que"],["even though + phrase","Even though it was late, she called.","même si, avec insistance"],["though en fin de phrase","It was cheap. It worked, though.","à l'oral : pourtant"]]},{"h":"whereas et while : deux faits côte à côte","p":"whereas et while comparent deux situations qui s'opposent, sans idée de surprise : He likes the city, whereas I prefer the countryside. C'est le « alors que » du contraste.\n\nwhile est plus courant à l'oral, whereas plus net à l'écrit. Attention, while veut aussi dire « pendant que »."}],"ex":[["Despite the traffic, we arrived on time.","Malgré la circulation, on est arrivés à l'heure.",""],["In spite of feeling ill, she went to work.","Bien qu'elle se sente malade, elle est allée travailler.","in spite of + -ing"],["Although the flat is small, it's very bright.","Bien que l'appartement soit petit, il est très lumineux.",""],["Even though I had set an alarm, I woke up late.","Même si j'avais mis un réveil, je me suis réveillé en retard.","even though souligne la surprise"],["My sister loves sport, whereas I prefer reading.","Ma sœur adore le sport, alors que je préfère lire.",""],["While some people work from home, others go to the office every day.","Alors que certains travaillent de chez eux, d'autres vont au bureau tous les jours.",""],["The plan failed despite the fact that everyone worked hard.","Le projet a échoué bien que tout le monde ait beaucoup travaillé.",""]],"traps":[["Despite of the rain, we went out.","Despite the rain, we went out.","despite ne prend jamais of."],["Despite it was raining, we went out.","Although it was raining, we went out.","despite ne peut pas être suivi d'une phrase complète."],["Although the rain, we went out.","Despite the rain, we went out.","although veut une phrase, pas un simple nom."]],"tip":"despite devant un nom, although devant une phrase, whereas entre deux faits qu'on compare."},
"subj":{"intro":"Dans un mail professionnel ou un compte rendu, tu recommandes ou exiges quelque chose : « je suggère qu'il parte tôt ». L'anglais soutenu a lui aussi un subjonctif, très simple.","parts":[{"h":"La forme : la base, pour tout le monde","p":"Le subjonctif anglais, c'est la base verbale, sans -s ni to, quel que soit le sujet : he leave, she be, they arrive.\n\nOn le trouve dans la subordonnée en that, après des verbes ou des expressions d'exigence, de conseil ou d'importance.","rows":[["suggest / recommend that","I suggest that he leave early.","pas de -s"],["insist / demand that","They insisted that she be present.","be pour tout le monde"],["it's essential / vital that","It's vital that everyone be told.","passif : be + participe"],["négation : not + base","We recommend that he not travel.","sans do"]]},{"h":"Les variantes plus courantes","p":"Ce subjonctif est surtout américain et formel. En anglais britannique et à l'oral, on dit souvent should + base : I suggest he should leave early.\n\nDans la langue courante, le présent normal se rencontre aussi : It's essential that everyone is on time. Il est accepté, mais moins soigné.","rows":[["subjonctif","I suggest he leave early.","formel, plutôt américain"],["should + base","I suggest he should leave early.","plutôt britannique"],["indicatif","It's essential that everyone is on time.","courant, moins soigné"]]},{"h":"suggest : la construction piège","p":"Sous l'influence du français, on est tenté de dire suggest someone to do. C'est faux.\n\nOn dit suggest that + sujet + base, ou suggest + -ing : I suggest leaving early."}],"ex":[["The doctor recommended that she rest for a week.","Le médecin a recommandé qu'elle se repose pendant une semaine.","rest, pas rests"],["It's essential that the contract be signed today.","Il est essentiel que le contrat soit signé aujourd'hui.",""],["They insisted that he pay the full price.","Ils ont exigé qu'il paie le plein tarif.",""],["I suggest that we meet on Monday instead.","Je suggère qu'on se voie plutôt lundi.",""],["The committee demanded that the report be published.","Le comité a exigé que le rapport soit publié.",""],["It's vital that nobody find out.","Il est vital que personne ne l'apprenne.","find, sans -s"],["We recommend that you not leave your bags unattended.","Nous vous recommandons de ne pas laisser vos bagages sans surveillance.","not + base"],["I suggest you should call them first.","Je te suggère de les appeler d'abord.","variante britannique"]],"traps":[["I suggest him to leave early.","I suggest that he leave early.","suggest ne se construit pas avec personne + to."],["She insisted that he leaves.","She insisted that he leave.","Au subjonctif, le verbe reste à la base, sans -s."],["We recommend that he doesn't travel.","We recommend that he not travel.","La négation du subjonctif est not + base, sans do."]],"tip":"Après suggest ou it's vital that, le verbe reste nu : he leave, she be."},
"hightime":{"intro":"« Il est grand temps qu'on parte », « tu ferais mieux de l'appeler », « je suis censé travailler » : trois tournures pour presser, conseiller ou rappeler ce qui est prévu.","parts":[{"h":"It's (high) time + prétérit","p":"It's time + sujet + prétérit dit qu'une chose aurait déjà dû arriver. high ou about renforcent l'impatience : It's high time we left.\n\nLe prétérit ne parle pas du passé : il marque l'écart entre ce qui est et ce qui devrait être. Sans sujet, on garde to : It's time to go.","rows":[["It's time to + base","It's time to go.","neutre"],["It's time + sujet + prétérit","It's time you went to bed.","léger reproche"],["It's high time / about time","It's high time we left.","impatience"]]},{"h":"had better + base","p":"had better, souvent contracté en 'd better, donne un conseil ferme, presque un avertissement : You'd better call him. On sous-entend une conséquence si on ne le fait pas.\n\nMalgré had, ça parle du présent ou du futur. Pas de to après, et la négation est had better not.","rows":[["You'd better + base","You'd better hurry.","tu ferais mieux de te dépêcher"],["You'd better not + base","You'd better not be late.","négation"]]},{"h":"be supposed to + base","p":"be supposed to veut dire être censé : une règle, un plan, une attente. I'm supposed to work tomorrow.\n\nAu passé, was supposed to sous-entend souvent que ça ne s'est pas fait : He was supposed to call me. Le -d de supposed s'entend à peine, mais il s'écrit.","rows":[["I'm supposed to…","I'm supposed to work tomorrow.","c'est prévu"],["You're not supposed to…","You're not supposed to park here.","c'est interdit"],["was supposed to…","The train was supposed to leave at six.","mais il n'est pas parti"]]}],"ex":[["It's high time you found a job.","Il est grand temps que tu trouves du travail.",""],["It's about time they fixed this road.","Il serait temps qu'ils réparent cette route.",""],["We'd better leave now, or we'll miss the train.","On ferait mieux de partir maintenant, sinon on va rater le train.",""],["You'd better not tell her.","Tu ferais mieux de ne pas lui dire.",""],["You're not supposed to eat in here.","On n'est pas censé manger ici.",""],["She was supposed to be here an hour ago.","Elle était censée être là il y a une heure.",""],["Isn't it time the kids went to bed?","Ce ne serait pas l'heure de coucher les enfants ?","prétérit après it's time"]],"traps":[["It's high time we leave.","It's high time we left.","Après It's time + sujet, le verbe passe au prétérit."],["You'd better to call him.","You'd better call him.","had better se construit sans to."],["I'm suppose to work tomorrow.","I'm supposed to work tomorrow.","On écrit supposed, avec -d, même si on l'entend à peine."]],"tip":"Grand temps : prétérit ; mieux vaut : had better sans to ; censé : supposed to."},
"participle":{"intro":"Dans un récit ou un rapport, tu veux enchaîner les actions sans alourdir : « Après avoir fini, elle est partie ». L'anglais condense avec une proposition en -ing ou en having.","parts":[{"h":"Les formes","p":"Une proposition participiale remplace une subordonnée entière. Elle n'a pas de sujet à elle : elle emprunte celui de la phrase principale.","rows":[["-ing","Walking home, I saw an accident.","actions en même temps"],["having + participe","Having finished, she left.","action terminée avant"],["participe passé","Built in 1890, the house needs work.","sens passif"],["not devant","Not knowing what to say, he stayed silent.","négation"]]},{"h":"Le même sujet, obligatoirement","p":"Le sujet sous-entendu de la participiale doit être celui de la principale. Sinon, la phrase devient absurde, ou drôle.\n\nWalking home, the rain started dit que c'est la pluie qui rentrait à pied. Il faut : Walking home, I got caught in the rain."},{"h":"Ce que ça exprime","p":"Selon le contexte, la participiale exprime le temps (après, pendant), la cause (comme, puisque) ou la manière. Not knowing what to say = comme il ne savait pas quoi dire.\n\nhaving + participe insiste sur l'ordre : la première action est finie. On peut aussi dire after + -ing : After finishing the report, she left."},{"h":"Comparaison avec le français","p":"Le français a les mêmes outils : « ne sachant pas quoi dire », « ayant fini ». Mais l'anglais les emploie bien plus, surtout à l'écrit.\n\nAprès une préposition comme after, before ou without, le verbe prend toujours -ing, jamais to."}],"ex":[["Having read the reviews, we decided to book another hotel.","Après avoir lu les avis, on a décidé de réserver un autre hôtel.",""],["Feeling tired, she went to bed early.","Comme elle se sentait fatiguée, elle s'est couchée tôt.","la cause"],["Not having a car, he takes the bus everywhere.","Comme il n'a pas de voiture, il prend le bus partout.",""],["Opening the door, I noticed a strange smell.","En ouvrant la porte, j'ai remarqué une odeur bizarre.","en même temps"],["Written in a hurry, the email was full of mistakes.","Écrit à la hâte, le mail était plein de fautes.","sens passif"],["Having lived in Spain, she speaks Spanish fluently.","Ayant vécu en Espagne, elle parle couramment espagnol.",""],["After graduating, he moved to Berlin.","Après avoir obtenu son diplôme, il s'est installé à Berlin.","after + -ing"]],"traps":[["Walking home, the rain started.","Walking home, I got caught in the rain.","Le sujet de la participiale doit être celui de la phrase principale."],["After to finish the report, she left.","After finishing the report, she left.","Après une préposition, le verbe prend -ing."],["Don't knowing what to say, he stayed silent.","Not knowing what to say, he stayed silent.","Une participiale se met à la négation avec not, sans do."]],"tip":"Une participiale n'a pas de sujet : elle prend celui de la phrase, alors vérifie qu'il colle."},
"idioms":{"intro":"Au travail ou entre amis, les natifs parlent en images : ça coûte un bras, on est dans le même bateau. Comprendre et placer ces expressions rend ton anglais naturel.","parts":[{"h":"Ne pas traduire mot à mot","p":"Une expression idiomatique a un sens global, que les mots pris un par un ne donnent pas. On apprend donc l'équivalent entier, comme un seul mot.\n\nSouvent, l'image change complètement d'une langue à l'autre : les yeux de la tête deviennent un bras et une jambe.","rows":[["coûter les yeux de la tête","cost an arm and a leg","autre image"],["il pleut des cordes","it's pouring","it's raining cats and dogs existe, mais fait un peu scolaire"],["poser un lapin","stand someone up","pas de lapin en anglais"],["c'est du gâteau","it's a piece of cake","presque la même image"]]},{"h":"Les images qui se ressemblent","p":"Certaines images existent dans les deux langues : on est dans le même bateau = we're in the same boat. Profites-en, mais vérifie toujours, car beaucoup se ressemblent sans être identiques.\n\nPar exemple, « tomber dans les pommes » ne se dit pas avec des pommes : on dit pass out.","rows":[["être dans le même bateau","be in the same boat","même image"],["briser la glace","break the ice","même image"],["tomber dans les pommes","pass out","pas d'image en anglais"],["avoir le cafard","feel blue","une couleur au lieu d'un insecte"]]},{"h":"Le registre et la forme figée","p":"Ces expressions vivent surtout à l'oral et dans l'écrit détendu. Dans un rapport formel, préfère un mot simple : expensive plutôt qu'an arm and a leg.\n\nUne expression est figée : on ne remplace pas ses mots. On dit a piece of cake, jamais a slice of cake. Seul le verbe se conjugue : It cost me an arm and a leg."}],"ex":[["That exam was a piece of cake.","Cet examen, c'était du gâteau.",""],["Don't worry, we're all in the same boat.","Ne t'inquiète pas, on est tous dans le même bateau.",""],["The tickets cost us an arm and a leg.","Les billets nous ont coûté les yeux de la tête.",""],["He stood me up last night.","Il m'a posé un lapin hier soir.",""],["Break a leg tonight!","Bonne chance pour ce soir !","se dit à quelqu'un qui monte sur scène : au théâtre, « good luck » porte malheur"],["It's pouring, so take an umbrella.","Il pleut des cordes, alors prends un parapluie.",""],["Let's call it a day.","On s'arrête là pour aujourd'hui.","call it a day = arrêter de travailler"],["She let the cat out of the bag about the party.","Elle a vendu la mèche pour la fête.","let the cat out of the bag = vendre la mèche"]],"traps":[["It costs the eyes of the head.","It costs an arm and a leg.","Une expression ne se traduit pas mot à mot."],["It's raining ropes.","It's pouring.","L'image des cordes n'existe pas en anglais."],["That exam was a slice of cake.","That exam was a piece of cake.","Une expression est figée : on ne change pas ses mots."]],"tip":"Une expression s'apprend en bloc : on ne la traduit pas, on la remplace."}
});
})();
